{
  "rules": [
    {
      "category": "rent_increase_limit",
      "title": "San Francisco Annual Allowable Rent Increase",
      "requirement": "Landlords may impose an annual rent increase on tenants in occupancy of up to 60% of the published CPI increase, capped at an absolute maximum of 7%. The increase requires proper written notice and landlord reporting compliance with the Rent Board.",
      "requirement_es": "Los propietarios pueden aplicar un aumento anual de alquiler a los inquilinos ocupantes de hasta el 60% del aumento del IPC publicado, con un tope máximo absoluto del 7%. El aumento requiere una notificación adecuada por escrito y el cumplimiento del registro del propietario ante la Junta de Alquileres.",
      "key_value": {
        "label": "Annual Rent Increase Cap",
        "value": "60% of CPI, maximum 7%"
      },
      "coverage_conditions": {
        "type": "AND",
        "clauses": [
          {
            "field": "certificate_of_occupancy_date",
            "operator": "<=",
            "value": "1979-06-13",
            "note": "dwelling or unit newly constructed and first received certificate of occupancy on or before June 13, 1979 unless exception applies"
          }
        ]
      },
      "exemptions": [
        {
          "description": "Accommodations in hotels, motels, inns, tourist houses, rooming/boarding houses occupied for less than 32 continuous days.",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "tenancy_length_months",
                "operator": "<",
                "value": 1,
                "note": "less than 32 continuous days"
              }
            ]
          }
        },
        {
          "description": "Dwelling units in non-profit cooperatives owned, occupied and controlled by a majority of the residents or solely owned by a non-profit public benefit corporation governed by a board where a majority are residents.",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "nonprofit"
              }
            ]
          }
        },
        {
          "description": "Housing accommodations in licensed hospitals, convents, monasteries, extended care facilities, asylums, residential care or adult day health care facilities, or school dormitories.",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "property_type",
                "operator": "==",
                "value": "other"
              }
            ]
          }
        },
        {
          "description": "Units whose rents are controlled or regulated by any government agency (with specific statutory exceptions).",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "rent_subsidized",
                "operator": "==",
                "value": true
              }
            ]
          }
        },
        {
          "description": "Separately alienable parcels (single-family homes, condominiums) under Costa-Hawkins where tenancy was created on or after January 1, 1996, subject to statutory limits.",
          "conditions": {
            "type": "OR",
            "clauses": [
              {
                "field": "property_type",
                "operator": "==",
                "value": "single_family"
              },
              {
                "field": "property_type",
                "operator": "==",
                "value": "condominium"
              }
            ]
          }
        },
        {
          "description": "Substantially rehabilitated buildings certified by the Rent Board (residential units 50+ years of age).",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "building_age_years",
                "operator": ">=",
                "value": 50
              }
            ]
          }
        }
      ],
      "effective_date": "2024-11-24",
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "yields_to",
        "target_scope": "state",
        "source_language": "Consistent with the Costa-Hawkins Rental Housing Act (Civil Code Sections 1954.50, et seq.) and regardless of whether otherwise provided under Chapter 37"
      },
      "penalty": "Any rent increase which does not conform with the provisions of this section shall be null and void.",
      "source_citation": "S.F. Admin. Code § 37.3(a)(1)",
      "quote": {
        "chunk": "c50",
        "start_words": "A landlord who has reported the required",
        "end_words": "greater than 7%."
      },
      "confidence": 0.95
    }
  ]
}
